{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.lb",
      "severity": "LOW",
      "explanation": "The security group and its rules lack descriptions, which makes it harder to understand their purpose and audit them effectively."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing unrestricted egress traffic to all destinations (0.0.0.0/0) on all ports is overly permissive and can expose the system to data exfiltration risks."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing unrestricted SSH access (port 22) from the internet (0.0.0.0/0) poses a significant security risk as it can be exploited for unauthorized access."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing unrestricted RDP access (port 3389) from the internet (0.0.0.0/0) poses a significant security risk as it can be exploited for unauthorized access."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 80",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing unrestricted HTTP access (port 80) from the internet (0.0.0.0/0) can expose the system to potential attacks if the web server is not properly secured."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "HIGH",
      "explanation": "Allowing unrestricted ingress traffic from the internet (0.0.0.0/0) on all ports is overly permissive and can expose the system to a wide range of attacks."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-all-lb\"\n  vpc_id      = data.aws_vpc.main.id\n  description = \"Security group for load balancer with restricted rules\"\n\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n    description = \"Allow HTTP traffic from the internet\"\n  }\n\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n    description = \"Allow all outbound traffic\"\n  }\n}",
  "fix_summary": "Descriptions were added to the security group and its rules for better documentation. Ingress rules were restricted to allow only HTTP traffic (port 80) from the internet, and overly permissive ingress rules for all ports and protocols were removed. Egress rules were left unchanged but now include a description."
}
